#!/usr/bin/env bash
# СУДИТ: hooks/root-cause-lib.sh hooks/five-whys-gate.sh scripts/outcome.sh
# probe_D1109 — исход сверяется с поводом ЭТОГО хода и с первой целью записи при нём, а не с «последним отказом рода в
# сессии» и не с текущей целью. Красная (1), пока: (а) сменой цели записи пункт о другом файле снимает отказ и для
# файла повода (M2); (б) тот же исход в новом ходе, названный до первой записи, в журнал не ложится (M3); (в) свежий пункт
# о предмете второго хода отвергается по цели первого (M4); (г) причина непринятого — не первая найденная (M6); (д) повтор
# исхода назван записью (M3). Положительный контроль — пункт по первой цели снимает отказ.
# Рамка не собралась — 2.
. "$(dirname "$0")/outcome_frame_lib.sh" || exit 2
# (а) повод про hooks/x.sh; пункт про y.sh; цель переносится на y.sh
P="$SB/a"; gproj "$P" || exit 2
TA="$SB/ta.jsonl"; mk_tr "$TA" "Побочно вылезла дыра в разборе ключа в hooks/x.sh, чиню заодно."
[ "$(dec "$(cw s1 "$P/hooks/x.sh" "$TA" "$P")")" = deny ] || exit 2
item "$P/BACKLOG.md" D9970 "hooks/y.sh:2"
no s1 debt discovery D9970 "$P"
cw s1 "$P/hooks/y.sh" "$TA" "$P" >/dev/null
no s1 debt discovery D9970 "$P"
cw s1 "$P/hooks/y.sh" "$TA" "$P" >/dev/null     # снятие сверкой по ТЕКУЩЕЙ цели — и память зачёта на весь повод
[ "$(dec "$(cw s1 "$P/hooks/x.sh" "$TA" "$P")")" = deny ] \
    || { echo "(а) пункт о другом файле после смены цели снял отказ для файла повода" >&2; exit 1; }
# Положительный контроль: пункт по первой цели — снимает
item "$P/BACKLOG.md" D9971 "hooks/x.sh:4"
no s1 debt discovery D9971 "$P" || { echo "пункт по первой цели не принят" >&2; exit 1; }
[ "$(dec "$(cw s1 "$P/hooks/x.sh" "$TA" "$P")")" = deny ] && { echo "пункт по первой цели не снял отказ" >&2; exit 1; }
# (б) ход 2: новый повод, проявление дописано в прежний пункт, исход назван до первой записи хода
P="$SB/b"; gproj "$P" || exit 2
TB="$SB/tb.jsonl"; mk_tr "$TB" "$FINDING"
cw s2 "$P/hooks/x.sh" "$TB" "$P" >/dev/null
item "$P/BACKLOG.md" D9980 "hooks/x.sh:2"
no s2 debt discovery D9980 "$P" || exit 2
next_turn "$TB" "дальше" "Побочно вылезла ещё дыра: ключ разбора съезжает, чиню заодно."
cr s2 "$TB" "$P"
printf '%s\n' '  **Проявление 2.** `hooks/x.sh:7` ключ съезжает.' >> "$P/BACKLOG.md"
_n0=$(grep -c '' "$ST/outcome-s2.jsonl" 2>/dev/null); _n0=${_n0:-0}
no s2 debt discovery D9980 "$P"
_n1=$(grep -c '' "$ST/outcome-s2.jsonl" 2>/dev/null); _n1=${_n1:-0}
[ "$_n1" -gt "$_n0" ] || { echo "(б) исход нового хода, названный до первой записи, в журнал не лёг" >&2; exit 1; }
# (в) ход 2: свежий пункт о предмете второго хода (y.sh), исход до первой записи хода
P="$SB/c"; gproj "$P" || exit 2
TC="$SB/tc.jsonl"; mk_tr "$TC" "$FINDING"
cw s3 "$P/hooks/x.sh" "$TC" "$P" >/dev/null
item "$P/BACKLOG.md" D9981 "hooks/x.sh:2"
no s3 debt discovery D9981 "$P" || exit 2
next_turn "$TC" "дальше" "Побочно вылезла ещё дыра в разборе ключа, чиню заодно."
cr s3 "$TC" "$P"
item "$P/BACKLOG.md" D9982 "hooks/y.sh:3"
no s3 debt discovery D9982 "$P" || { echo "(в) свежий пункт о предмете второго хода отвергнут по цели первого" >&2; exit 1; }
# (г) причина непринятого исхода — ПЕРВАЯ найденная (M6, D1120): у пункта проекта нет адреса, а одноимённый пункт
# ClaudSoul (D1108 в архиве) отвергается по свежести — команда обязана назвать причину пункта проекта.
P="$SB/d"; gproj "$P" || exit 2
TD="$SB/td.jsonl"; mk_tr "$TD" "$FINDING"
[ "$(dec "$(cw s4 "$P/hooks/x.sh" "$TD" "$P")")" = deny ] || exit 2
printf '%s\n' '- ☐ **D1108** пункт проекта без адреса' '  **Корень.** R6 — два состояния.' >> "$P/BACKLOG.md"
why=$( cd "$P" && DIS_SESSION=s4 STATE_DIR="$ST" bash "$OUTCMD" debt discovery D1108 2>&1 >/dev/null ) && exit 2
grep -q 'нет адреса проявления' <<< "$why" || { echo "(г) причина — не первая найденная: $why" >&2; exit 1; }
# (д) повтор того же исхода в ходе назван повтором, а не выдан за запись (M3, D1120; канал сменён D1139: находка, уже
# снятая в ходе, повторно не судится — команда отвечает отказом «уже принят» в stderr, а не строкой «уже записан» в stdout)
again=$( cd "$SB/a" && DIS_SESSION=s1 STATE_DIR="$ST" bash "$OUTCMD" debt discovery D9971 2>&1 )
{ grep -qE 'уже (принят|записан)' <<< "$again" && ! grep -q '^исход записан:' <<< "$again"; } \
    || { echo "(д) повтор исхода назван записью: $again" >&2; exit 1; }
# (е) повтор без живого повода проходит мимо отказа D1139 и доходит до дедупа пары — ветки, которую чинил сам D1109
# (`scripts/outcome.sh`, «уже записан в этом ходе»); (д) её не достаёт (скептик opus по d271f058, M2).
P="$SB/e"; mkdir -p "$P"
e1=$( cd "$P" && DIS_SESSION=s5 STATE_DIR="$ST" bash "$OUTCMD" disproved streak "повтор без повода: довод" 2>&1 )
e2=$( cd "$P" && DIS_SESSION=s5 STATE_DIR="$ST" bash "$OUTCMD" disproved streak "повтор без повода: довод" 2>&1 )
grep -q '^исход записан:' <<< "$e1" || { echo "контроль (е): первый исход не записан: $e1" >&2; exit 2; }
{ grep -q 'уже записан в этом ходе' <<< "$e2" && ! grep -q '^исход записан:' <<< "$e2"; } \
    || { echo "(е) повтор исхода в дедупе пары назван записью: $e2" >&2; exit 1; }
echo "исход сверяется с поводом хода и первой целью: смена цели не снимает, повтор пишется, чужой ход не судит"
exit 0
